mapper.select:
SELECT user_id userId
FROM pubcar_car_user
WHERE community_id = #{communityId} AND status_cd = '0' AND is_self_driving = #{isSelfDriving}

    AND user_id IN

        #{item}



    AND user_id = #{userId}


    AND car_user_id <> #{carUserId}

SELECT pcu.user_id userId, uu.`name`, uu.sex gender, uu.job_num jobNum, uo.org_name department, d.`name` position, uu.tel FROM pubcar_car_user pcu LEFT JOIN u_user uu ON uu.user_id = pcu.user_id LEFT JOIN u_org_staff_rel r ON r.staff_id = uu.user_id LEFT JOIN u_org uo ON uo.org_id = r.org_id LEFT JOIN t_dict d ON d.status_cd = r.rel_cd WHERE d.table_name = 'u_org_staff_rel' AND d.table_columns = 'rel_cd' AND pcu.status_cd = '0' AND uu.level_cd = '01' and r.status_cd = '0' AND pcu.is_self_driving = '0' AND pcu.user_id NOT IN ( SELECT t.user_id FROM pubcar_car_user t WHERE t.is_self_driving = '1' AND t.status_cd = '0' )
and uu.name like concat('%',#{name},'%')
and uu.sex = #{gender}
and uo.org_name like concat('%',#{department},'%')
and d.name like concat('%',#{position},'%')
and uu.job_num like concat('%',#{jobNum},'%')
and pcu.community_id = #{communityId}
limit #{page}, #{row}

SELECT uo.org_id departmentId, uo.org_name department,
       (CASE WHEN SUM(trm.avgTripMileage) IS NULL THEN 0 ELSE SUM(trm.avgTripMileage) END) mileage,
       (CASE WHEN ROUND(SUM(trm.duration)) IS NULL THEN 0 ELSE CAST(SUM(trm.duration) AS UNSIGNED) END) duration,
       COUNT(DISTINCT trm.trip_id) tripNum
FROM u_org uo
LEFT JOIN u_org_staff_rel uosr ON uosr.org_id = uo.org_id
LEFT JOIN pubcar_trip pt ON pt.user_id = uosr.staff_id
LEFT JOIN (
    SELECT trip_id, AVG(pass_mileage) avgTripMileage, AVG(duration) duration
    FROM pubcar_trip_mileage
    /*pass_mileage IS NOT NULL 表明该行程结束，而非进行中*/
    WHERE status_cd = '0' AND pass_mileage IS NOT NULL
    /*下面的startTime和endTime是数据看板中需要的参数*/

         and start_time >= #{startTime}


         and end_time <= #{endTime}

    GROUP BY trip_id
) trm ON trm.trip_id = pt.trip_id
WHERE uo.store_id = #{storeId} AND uo.org_level = 3 AND uo.status_cd = '0'

    and uo.org_name like concat('%',#{department},'%')


     and pt.start_time >= #{lessStartTime}


     and pt.start_time <= #{moreStartTime}


     and pt.end_time >= #{lessEndTime}


     and pt.end_time <= #{moreEndTime}

GROUP BY uo.org_id

    limit #{page}, #{row}

SELECT count(DISTINCT uo.org_id) count
FROM u_org uo
LEFT JOIN u_org_staff_rel uosr ON uosr.org_id = uo.org_id
LEFT JOIN pubcar_trip pt ON pt.user_id = uosr.staff_id
LEFT JOIN pubcar_trip_mileage trm ON trm.trip_id = pt.trip_id
WHERE uo.store_id = #{storeId} AND uo.org_level = 3

    and uo.org_name like concat('%',#{department},'%')


     and pt.start_time >= #{lessStartTime}


     and pt.start_time <= #{moreStartTime}


     and pt.end_time >= #{lessEndTime}


     and pt.end_time <= #{moreEndTime}

mapper.sql:
FROM pubcar_car_user pcu LEFT JOIN u_user uu ON pcu.user_id = uu.user_id LEFT JOIN u_org_staff_rel uosr ON uu.user_id = uosr.staff_id LEFT JOIN u_org uo ON uosr.org_id = uo.org_id LEFT JOIN t_dict d ON d.status_cd = uosr.rel_cd WHERE uu.status_cd = '0' AND uo.status_cd = '0' AND uosr.status_cd = '0' AND pcu.status_cd = '0' AND d.table_name = 'u_org_staff_rel' AND d.table_columns = 'rel_cd' and pcu.is_self_driving = #{isSelfDriving}
and uosr.store_id = #{storeId}
and uu.tel like concat('%',#{tel},'%')
and uu.name like concat('%',#{name},'%')
and uo.org_name like concat('%',#{department},'%')
and d.name like concat('%',#{position},'%')
and uu.job_num like concat('%',#{jobNum},'%')
order by pcu.create_time desc
limit #{page}, #{row}

