insert into pubcar_car_user(car_user_id, user_id, is_self_driving, community_id, b_id, status_cd)
select t.car_user_id, t.user_id, t.is_self_driving, t.community_id, t.b_id, '0'
from business_pubcar_car_user t


        t.b_id= #{bId}


        and t.operate= #{operate}

