select t.car_user_id carUserId, t.user_id userId, t.is_self_driving isSelfDriving, t.community_id communityId, t.b_id bId
from pubcar_car_user t


        t.status_cd= #{statusCd}


        and t.b_id= #{bId}


        and t.car_user_id= #{carUserId}


order by t.create_time desc

    limit #{page}, #{row}

