SELECT uu.user_id userId, uu.`name`, uu.sex gender, uu.job_num jobNum, uo.org_name department, d.`name` `position`, uu.tel FROM u_user uu LEFT JOIN u_org_staff_rel r ON r.staff_id = uu.user_id LEFT JOIN u_org uo ON uo.org_id = r.org_id LEFT JOIN t_dict d ON d.status_cd = r.rel_cd WHERE d.table_name = 'u_org_staff_rel' AND d.table_columns = 'rel_cd' AND uu.status_cd = '0' AND uu.level_cd = '01' AND r.status_cd = '0'
and uu.user_id = #{currentUserId}
and uu.tel= #{tel}
and uu.name like concat('%',#{name},'%')
and uo.org_name like concat('%',#{department},'%')
and d.name like concat('%',#{position},'%')
and uu.job_num like concat('%',#{jobNum},'%')
limit #{page}, #{row}
